package longcontext

import("context";"database/sql";"os";"testing";"time";_ "github.com/lib/pq")
func TestAttemptFailureIntegration(t *testing.T){dsn:=os.Getenv("LLM_GATEWAY_TEST_DSN");if dsn==""{t.Skip("missing dsn")};db,e:=sql.Open("postgres",dsn);if e!=nil{t.Fatal(e)};defer db.Close();r,_:=NewPostgresRepository(db);ctx:=context.Background();id:="lct_attempt_test_"+time.Now().Format("20060102150405.000000000");tenant:="attempt-test";defer db.ExecContext(ctx,`DELETE FROM long_context_tasks WHERE id=$1`,id);if _,_,e=r.CreateTask(ctx,CreateTaskInput{ID:id,TenantID:tenant,Model:"virtual-long-1m",Mode:"qa",Query:"q",InputSHA256:HashInput("text"),WorkerCount:1,RetrievalTopK:1,FinalBudget:16000});e!=nil{t.Fatal(e)};if e=r.PersistChunks(ctx,id,tenant,"text",10,0);e!=nil{t.Fatal(e)};c,e:=r.ClaimChunk(ctx,id,"w",time.Minute);if e!=nil||c==nil{t.Fatalf("claim=%v",e)};if e=r.RecordAttempt(ctx,Attempt{TaskID:id,ChunkID:c.ID,Phase:"mapping",Model:"m",Provider:"nvidia-nim-key-01",Status:"failed",ErrorType:"provider_error",ErrorMessage:"test failure"});e!=nil{t.Fatal(e)};if e=r.MarkChunkFailed(ctx,c.ID,id,"test failure");e!=nil{t.Fatal(e)};var n int;if e=db.QueryRowContext(ctx,`SELECT count(*) FROM long_context_attempts WHERE task_id=$1`,id).Scan(&n);e!=nil||n!=1{t.Fatalf("attempts=%d err=%v",n,e)};var st string;if e=db.QueryRowContext(ctx,`SELECT status FROM long_context_chunks WHERE id=$1`,c.ID).Scan(&st);e!=nil||st!="failed"{t.Fatalf("chunk=%s err=%v",st,e)}}
